function cbCheck(n, r, needR){
  if(typeof n!=='number'||!isFinite(n)||Math.floor(n)!==n||n<0) return 'n 必须是非负整数';
  if(n>5000) return 'n 过大（≤5000）';
  if(needR){
    if(typeof r!=='number'||!isFinite(r)||Math.floor(r)!==r||r<0) return 'r 必须是非负整数';
    if(r>n) return 'r 不能大于 n';
  }
  return null;
}
function cbFact(n){
  var e=cbCheck(n,0,false); if(e) return { value:null, error:e };
  var v=1n;
  for(var i=2n;i<=BigInt(n);i++) v*=i;
  return { value:v, error:null };
}
function cbNcr(n,r){
  var e=cbCheck(n,r,true); if(e) return { value:null, error:e };
  var k=Math.min(r,n-r), v=1n;
  for(var i=0;i<k;i++) v=v*BigInt(n-i)/BigInt(i+1);
  return { value:v, error:null };
}
function cbNpr(n,r){
  var e=cbCheck(n,r,true); if(e) return { value:null, error:e };
  var v=1n;
  for(var i=0;i<r;i++) v*=BigInt(n-i);
  return { value:v, error:null };
}
function cbCatalan(n){
  var e=cbCheck(n,0,false); if(e) return { value:null, error:e };
  var c=cbNcr(2*n>5000?0:2*n, n);
  if(2*n>5000) return { value:null, error:'n 过大（Catalan 需 2n≤5000）' };
  return { value:c.value/BigInt(n+1), error:null };
}
function cbPascal(rows){
  if(typeof rows!=='number'||Math.floor(rows)!==rows||rows<1||rows>50) return { value:null, error:'行数需 1..50' };
  var tri=[[1n]];
  for(var i=1;i<rows;i++){
    var prev=tri[i-1], row=[1n];
    for(var j=1;j<i;j++) row.push(prev[j-1]+prev[j]);
    row.push(1n);
    tri.push(row);
  }
  return { value:tri, error:null };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { cbFact:cbFact, cbNcr:cbNcr, cbNpr:cbNpr, cbCatalan:cbCatalan, cbPascal:cbPascal };
}
if (typeof window !== 'undefined') {
  window.CombForgePure = { cbFact:cbFact, cbNcr:cbNcr, cbNpr:cbNpr, cbCatalan:cbCatalan, cbPascal:cbPascal };
}
